def transform(grid):
    # No single candidate reproduced all eight demonstration pairs; retain the
    # previously stored task program unchanged per the task's save instruction.
    return [row[:] for row in grid]
def transform(grid):
    n = len(grid[0])
    mid = next((j for j, v in enumerate(grid[0]) if v == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        # Expand the two diagonal arms of the 2-colored V.
        if r <= mid:
            for c in (mid - r, mid + r):
                if 0 <= c < n:
                    out[r][c] = 2
        # A period-four diagonal lattice of 1s fills the central region.
        lo, hi = max(0, mid - r), min(n - 1, mid + r)
        for c in range(lo, hi + 1):
            if (c - r - mid) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
def transform(grid):
    n = len(grid)
    # Repeating diagonal checker pattern; color depends on parity of r-c.
    return [[6 if (r - c) % 2 == 0 else 5 for c in range(n)] for r in range(n)]

