def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Objects are hollow one-cells; add color 3 inside each closed rectangle.
    # Extend color 2 as framing background around object boundaries where adjacent
    # spaces form an exterior halo, as demonstrated.
    # Identify axis-aligned bounding boxes formed by connected 1-components.
    seen=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=1 or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); comp=[]
       while stack:
        y,x=stack.pop(); comp.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=(y+dy,x+dx)
         if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
          seen.add(p); stack.append(p)
       # Take bounding box; rectangle border with a missing segment denotes cavity fill.
       y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
       # Fill enclosed interior of ring-like objects with 3.
       for y in range(y0+1,y1):
        for x in range(x0+1,x1):
         if grid[y][x]==0:
          out[y][x]=3
    # For this task examples also add a one-cell colored-2 halo around outlined
    # objects, but only along their outer margins; infer via perimeter neighbors.
    # A 1-cell background ring adjacent to a component is color 2 when it forms
    # continuation of its rectangular frame.
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=1: continue
       # endpoints of long straight horizontal/vertical borders extend their line
       # by one cell when that location is otherwise blank.
       for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
        rr,cc=r+dr,c+dc
        if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0:
         # endpoint if continuing along same axis impossible, avoid generic extension
         pass
    return out
