def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Paint 3 in enclosed zero areas belonging to each 1 outline; color its
    # immediate exterior rectangular border 2.
    from collections import deque
    visited=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=1 or (r,c) in visited: continue
       stack=[(r,c)]; visited.add((r,c)); comp=[]
       while stack:
        y,x=stack.pop(); comp.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=(y+dy,x+dx)
         if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in visited: visited.add(p); stack.append(p)
       y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
       # find bounded zero pockets in the component's bounding rectangle
       z={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if grid[y][x]==0}
       border=set(); q=deque()
       for y,x in z:
        if y in (y0,y1) or x in (x0,x1): border.add((y,x)); q.append((y,x))
       while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         p=(y+dy,x+dx)
         if p in z and p not in border: border.add(p); q.append(p)
       pocket=z-border
       if not pocket: continue
       for y,x in pocket: out[y][x]=3
       # halo around full rectangle enclosing the original 1 component
       for x in range(x0,x1+1):
        for y in (y0-1,y1+1):
         if 0<=y<h and grid[y][x]==0: out[y][x]=2
       for y in range(y0,y1+1):
        for x in (x0-1,x1+1):
         if 0<=x<w and grid[y][x]==0: out[y][x]=2
    return out
